const TEMPLATE_FILES={"xl/workbook.xml":"","xl/styles.xml":"","xl/theme/theme1.xml":"","xl/sharedStrings.xml":"","xl/worksheets/sheet1.xml":"","_rels/.rels":"","xl/_rels/workbook.xml.rels":"","[Content_Types].xml":""};
const utf8=new TextEncoder();
function decode64(b){const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u}
const crctable=(()=>{let t=[];for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=c&1?0xedb88320^(c>>>1):c>>>1;t.push(c>>>0)}return t})();
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crctable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function zipStore(files){const chunks=[],central=[];let offset=0;const u16=(v)=>[v&255,(v>>>8)&255],u32=v=>[v&255,(v>>>8)&255,(v>>>16)&255,(v>>>24)&255];for(const [name,data] of Object.entries(files)){const nb=utf8.encode(name),crc=crc32(data),size=data.length;const local=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(size),...u32(size),...u16(nb.length),...u16(0),...nb]);chunks.push(local,data);central.push(new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(size),...u32(size),...u16(nb.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...nb]));offset+=local.length+size}const start=offset;for(const c of central){chunks.push(c);offset+=c.length}chunks.push(new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(central.length),...u16(central.length),...u32(offset-start),...u32(start),...u16(0)]));return new Blob(chunks,{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function exportMedware(){const missions=filtered();if(missions.length>30){alert('Le modèle MEDWARE contient 30 lignes de missions (10 à 39). Ce mois comporte '+missions.length+' missions. Export impossible sans agrandir le modèle.');return}const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main',file='xl/worksheets/sheet1.xml';const doc=new DOMParser().parseFromString(new TextDecoder().decode(decode64(TEMPLATE_FILES[file])),'application/xml');if(doc.querySelector('parsererror'))throw Error('Modèle XML invalide');const rows=Array.from(doc.getElementsByTagNameNS(ns,'row'));const byrow=Object.fromEntries(rows.map(r=>[Number(r.getAttribute('r')),r]));function cell(ref){let rowNum=Number(ref.match(/\d+/)[0]),r=byrow[rowNum];if(!r)throw Error('Ligne manquante '+rowNum);let c=Array.from(r.getElementsByTagNameNS(ns,'c')).find(x=>x.getAttribute('r')===ref);if(!c){c=doc.createElementNS(ns,'c');c.setAttribute('r',ref);let next=Array.from(r.children).find(x=>x.localName==='c'&&colnum(x.getAttribute('r'))>colnum(ref));r.insertBefore(c,next||null)}return c}function colnum(ref){let n=0;for(const x of ref.match(/^[A-Z]+/)[0])n=n*26+x.charCodeAt(0)-64;return n}function set(ref,value,formula){const c=cell(ref);for(const x of Array.from(c.children))if(['v','f','is'].includes(x.localName))c.removeChild(x);if(value===null||value===undefined||value===''){c.removeAttribute('t');return}if(typeof value==='string'){c.setAttribute('t','inlineStr');let is=doc.createElementNS(ns,'is'),t=doc.createElementNS(ns,'t');t.textContent=value;is.appendChild(t);c.appendChild(is)}else{c.removeAttribute('t');if(formula){const f=doc.createElementNS(ns,'f');f.textContent=formula;c.appendChild(f)}let v=doc.createElementNS(ns,'v');v.textContent=String(value);c.appendChild(v)}}function serial(d){const dt=new Date(d+'T00:00:00Z');return Number.isFinite(dt.getTime())?Math.round((dt.getTime()-Date.UTC(1899,11,30))/86400000):null}const cols=['A','B','C','E','F','G','H','I','J','K','L','M','N','O','P'];const totals=Object.fromEntries(['G','H','I','J','K','L','M','N','O'].map(c=>[c,0]));for(let i=0;i<30;i++){const r=i+10,m=missions[i];if(!m){for(const col of cols)set(col+r,null);continue}const rate=num(state.rate),km=num(m.km),values=[serial(m.date),m.purpose||'',m.place||'',km,rate,Math.round(km*rate*100)/100,num(m.toll),num(m.allowance),num(m.meal),num(m.hotel),num(m.train),num(m.other),num(m.parking),num(m.reception),m.notes||''];for(let j=0;j<cols.length;j++)set(cols[j]+r,values[j],cols[j]==='G'?'E'+r+'*F'+r:null);for(const c of Object.keys(totals))totals[c]+=values[cols.indexOf(c)]||0}for(const c of Object.keys(totals))set(c+'40',Math.round(totals[c]*100)/100,'SUM('+c+'10:'+c+'39)');const total=Object.values(totals).reduce((a,b)=>a+b,0),advance=num(state.months[month()]);set('P42',Math.round(total*100)/100,'SUM(G40:O40)');set('P44',advance);set('P46',Math.round((total-advance)*100)/100,'P42-P44');const date=new Date(month()+'-01T00:00:00Z');const period=date.toLocaleDateString('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'}).toUpperCase();set('B4','Période : '+period);const files={};for(const [name,b64] of Object.entries(TEMPLATE_FILES)){if(name===file){files[name]=utf8.encode(new XMLSerializer().serializeToString(doc));}else if(name==='xl/sharedStrings.xml'){const shared=new DOMParser().parseFromString(new TextDecoder().decode(decode64(b64)),'application/xml');if(shared.querySelector('parsererror'))throw Error('Chaînes du modèle invalides');const nsShared='http://schemas.openxmlformats.org/spreadsheetml/2006/main';const strings=shared.getElementsByTagNameNS(nsShared,'si');const p=typeof getProfile==='function'?getProfile():{lastName:'OUAID',firstName:'Haitham',service:'CRHF'};if(strings.length<2)throw Error('En-tête MEDWARE introuvable');const setShared=(item,value)=>{const t=item.getElementsByTagNameNS(nsShared,'t')[0];if(!t)throw Error('En-tête manquant');t.textContent=value;};setShared(strings[0],'Nom & Prénom : '+[p.lastName,p.firstName].filter(Boolean).join(' '));setShared(strings[1],'Service : '+(p.service||''));files[name]=utf8.encode(new XMLSerializer().serializeToString(shared));}else files[name]=decode64(b64);}const blob=zipStore(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='NOTE_DE_FRAIS_MEDWARE_'+month()+'.xlsx';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)}
